269	  exactKeys(raw, ['tick', 'unit', 'seq', 'command'], 'input');
270	  requireKeys(raw, ['tick', 'unit', 'command'], 'input');
271	  const tick = integer(raw.tick, 'input tick', 0, MAX_TICKS_LIMIT - 1);
272	  const unit = identifier(raw.unit, 'input unit');
273	  const seq = raw.seq === undefined ? 0 : integer(raw.seq, 'input seq', 0, 2147483647);
274	  const command = raw.command;
275	  exactKeys(command, ['kind', 'position', 'by', 'velocity', 'attacking'], 'input command');
276	  if (command.kind === 'move') {
277	    const present = ['position', 'by', 'velocity'].filter((key) => command[key] !== undefined);
278	    if (present.length !== 1) {
279	      throw new ValidationError('a move command must contain exactly one of position, by, or velocity');
280	    }
281	    if (command.position !== undefined) {
282	      return { command: { kind: 'move', position: integer(command.position, 'move position', POSITION_MIN, POSITION_MAX) }, seq, tick, unit };
283	    }
284	    if (command.by !== undefined) {
285	      return { command: { by: integer(command.by, 'move by', -POSITION_MAX, POSITION_MAX), kind: 'move' }, seq, tick, unit };
286	    }
287	    return { command: { kind: 'move', velocity: integer(command.velocity, 'move velocity', -POSITION_MAX, POSITION_MAX) }, seq, tick, unit };
288	  }
289	  if (command.kind === 'attack') {
290	    if (typeof command.attacking !== 'boolean' || command.position !== undefined
291	      || command.by !== undefined || command.velocity !== undefined) {
292	      throw new ValidationError('an attack command must contain exactly kind and a boolean attacking');
293	    }
294	    return { command: { attacking: command.attacking, kind: 'attack' }, seq, tick, unit };
295	  }
296	  throw new ValidationError(`input command kind must be one of ${COMMAND_ORDER.join(', ')}`);
297	}
298	
299	/** Drop the arrival tag so replay documents stay canonical. */
300	function stripInput(input) {
301	  return { command: input.command, tick: input.tick, unit: input.unit };
302	}
303	
304	/**
305	 * Canonical JSON of one input record. It covers tick, unit and command only -
306	 * never the arrival order or the arrival sequence - so resubmitting the same
307	 * record, or delivering it late, produces the same canonical bytes.
308	 */
309	function canonicalInput(input) {
310	  const command = input.command.kind === 'move'
311	    ? { by: input.command.by, kind: 'move', position: input.command.position, velocity: input.command.velocity }
312	    : { attacking: input.command.attacking, kind: 'attack' };
313	  return `{"command":${JSON.stringify(command)},"tick":${input.tick},"unit":${JSON.stringify(input.unit)}}`;
314	}
315	
316	/** Order two input records inside the same tick: move before attack, then unit id. */
317	function compareInputs(left, right) {
318	  if (left.tick !== right.tick) {
319	    return left.tick - right.tick;
320	  }
321	  const rank = COMMAND_RANK[left.command.kind] - COMMAND_RANK[right.command.kind];
322	  return rank !== 0 ? rank : (left.unit < right.unit ? -1 : left.unit > right.unit ? 1 : 0);
323	}
324	
325	/**
326	 * Canonical state hash:
327	 *
328	 *   payload = '{"team_damage":{"blue":<n>,"red":<n>},"tick":<n>,"units":[' +
329	 *             alive units sorted by id, then dead units sorted by id, each as
330	 *             '{"attacking":<bool>,"health":<n|null>,"id":"<id>","position":<n>,'
331	 *             + '"team":"<red|blue>","velocity":<n>}' +
332	 *             '],"version":1}'
333	 *   state_hash = sha256('lockstepnet.state.v1\n' + payload) as lowercase hex
334	 *
335	 * Every number is an integer and the field order is fixed, so the payload is a
336	 * byte-exact function of the state.
337	 */
338	function stateHash(state) {
339	  const entries = [];
340	  for (const unit of liveUnits(state)) {
341	    entries.push(
342	      `{"attacking":${unit.attacking === true},"health":${unit.health},"id":${JSON.stringify(unit.id)},`
343	        + `"position":${unit.position},"team":${JSON.stringify(unit.team)},"velocity":${unit.velocity}}`,
344	    );
345	  }
346	  for (const unit of Object.values(state.units).filter((candidate) => candidate.health <= 0).sort(byId)) {
347	    entries.push(
348	      `{"attacking":false,"health":null,"id":${JSON.stringify(unit.id)},`
349	        + `"position":${unit.position},"team":${JSON.stringify(unit.team)},"velocity":${unit.velocity}}`,
350	    );
351	  }
352	  const payload = `{"team_damage":{"blue":${state.teamDamage.blue},"red":${state.teamDamage.red}},`
353	    + `"tick":${state.tick},"units":[${entries.join(',')}],"version":${SCHEMA_VERSION}}`;
354	  return createHash('sha256').update(`${STATE_DOMAIN}${payload}`).digest('hex');
355	}
356	
357	/** sha256 over the canonical form of a list of input records; order-insensitive. */
358	function inputSetHash(inputs) {
359	  const hash = createHash('sha256');
360	  for (const row of inputs.map(canonicalInput).sort()) {
361	    hash.update(row);
362	    hash.update('\n');
363	  }
364	  return hash.digest('hex');
365	}
366	
367	/** Fingerprint of a recorded replay: inputs (order-insensitive) plus frame hashes. */
368	function fileHash(config, inputs, frames) {
369	  const text = JSON.stringify({
370	    hashes: frames.map((frame) => frame.state_hash),
371	    inputs: inputs.map(canonicalInput).sort(),
372	    match: { id: config.id, max_ticks: config.maxTicks, seed: config.seed, units: config.units },
373	    schema: SCHEMA_VERSION,
374	    ticks: frames.map((frame) => frame.tick),
375	  });
376	  return createHash('sha256').update(`lockstepnet.replay.v1\n${text}`).digest('hex');
377	}
378	
379	module.exports = {
380	  ATTACK_BASE, COMMAND_ORDER, HEALTH_MAX, MAX_STEP, MAX_TICKS_LIMIT, MAX_UNITS,
381	  POSITION_MAX, POSITION_MIN, SCHEMA_VERSION, TEAMS,
382	  applyTick, canonicalInput, cloneState, compareInputs, exactKeys, fileHash,
383	  identifier, initialState, inputSetHash, integer, liveUnits, parseConfig,
384	  parseInputRecord, stateHash, stripInput,
385	};
