    );
    rejects({ id: 'bad id', delay_ticks: 0 });
    rejects({ id: 9, delay_ticks: 0 });
    rejects({ id: 'cam2' });
    rejects({ id: 'cam2', delay_ticks: -1 });
    rejects({ id: 'cam2', delay_ticks: 1025 });
    rejects({ id: 'cam2', delay_ticks: 1.5 });
