    .prepare('INSERT INTO spectators(match_id, id, delay_ticks, high_water, reset) VALUES (?, ?, ?, ?, ?)')
    .run(matchId, spectator.id, spectator.delayTicks, spectator.highWater, spectator.reset ? 1 : 0);
}

readSpectator(matchId, spectatorId) {
  const row = this.connection
    .prepare('SELECT * FROM spectators WHERE match_id = ? AND id = ?')
    .get(matchId, spectatorId);
  return row
